void W3DPropDraw::reactToTransformChange(const Matrix3D *, const Coord3D *, Real)
{
	Drawable *draw = getDrawable();
	if (m_propAdded)
		return;

	const Coord3D *position = draw->getPosition();
	if (position->x == 0.0f && position->y == 0.0f)
		return;

	m_propAdded = true;
	const ModuleData *data = getModuleData();
	const W3DPropDrawModuleData *moduleData = data ? data->getAsW3DPropDrawModuleData() : 0;
	if (moduleData == 0)
		return;

	TheTerrainRenderObject->addProp(draw->getID(), *position, draw->m_unk0x44.x, draw->m_instanceScale,
		moduleData->ModelName, moduleData->DistanceFog);
}

